/// @f$ f(k; M, K, N) = \binom{K}{k}\,\binom{M-K}{N-k} \big/ \binom{M}{N} @f$.
/// 
/// @param k   Evaluation points (any shape).
/// @param M   Population size.
pub fn hygepdf(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "hygepdf", args, 1)?;
    Ok(outs.pop().unwrap())
}
pub fn hygepdf_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "hygepdf", args, nargout)
}
/// Strongly-typed wrapper for `stats::hygepdf` generated from its C++ header.
pub fn hygepdf_typed(ctx: &Context, p_0_k: &Value, p_1_m: f64, p_2_k: f64, p_3_n: f64) -> Result<Value, Error> {
    let v_1 = (p_1_m).into_numkit_value()?;
    let v_2 = (p_2_k).into_numkit_value()?;
    let v_3 = (p_3_n).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "hygepdf", &[p_0_k, &v_1, &v_2, &v_3], 1)?;
    Ok(outs.pop().unwrap())
}

