/// @brief Hypergeometric mean and variance (`[m, v] = hygestat(M, K, N)`).
/// 
/// Closed form:
/// `m = N·K/M`,
/// `v = N·K·(M-K)·(M-N) / (M² · (M-1))`.
/// 
pub fn hygestat(ctx: &Context, args: &[&Value]) -> Result<(Value, Value), Error> {
    let mut outs = ctx.call(TOOLBOX, "hygestat", args, 2)?;
    let b = outs.pop().unwrap();
    let a = outs.pop().unwrap();
    Ok((a, b))
}
pub fn hygestat_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "hygestat", args, nargout)
}
