pub fn hygestat_typed(ctx: &Context, p_0_m: f64, p_1_k: f64, p_2_n: f64) -> Result<(Value, Value), Error> {
    let v_0 = (p_0_m).into_numkit_value()?;
    let v_1 = (p_1_k).into_numkit_value()?;
    let v_2 = (p_2_n).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "hygestat", &[&v_0, &v_1, &v_2], 2)?;
    let b = outs.pop().unwrap();
    let a = outs.pop().unwrap();
    Ok((a, b))
}

